LOGICPULSE.UI.HUDButton = class extends LOGICPULSE.UI.Element {
    constructor(options) {
        super();
        options = options || {};
        this._idleBitmap = options.idleBitmap;
        this._hoverBitmap = options.hoverBitmap;
        this._width = options.width || 100;
        this._height = options.height || 40;
        this._text = options.text || "";
        this._onClick = options.onClick || null;
        this._isHovered = false;
        this._textOffsetX = options.textOffsetX || 0;
        this._textOffsetY = options.textOffsetY || 0;
        this.move(options.x || 0, options.y || 0);
        this.create();
    }

    create() {
        // Idle sprite
        if (this._idleBitmap) {
            this._idleSprite = new Sprite(this._idleBitmap);
            this._idleSprite.width = this._width;
            this._idleSprite.height = this._height;
            this.addChild(this._idleSprite);
        }
        // Hover sprite
        if (this._hoverBitmap) {
            this._hoverSprite = new Sprite(this._hoverBitmap);
            this._hoverSprite.width = this._width;
            this._hoverSprite.height = this._height;
            this._hoverSprite.visible = false;
            this.addChild(this._hoverSprite);
        }
        // Text
        if (this._text) {
            this._textSprite = new Sprite(new Bitmap(this._width, this._height));
            this._textSprite.bitmap.fontFace = $gameSystem.mainFontFace();
            this._textSprite.bitmap.fontSize = this.options && this.options.fontSize ? this.options.fontSize : 20;
            this._textSprite.bitmap.textColor = "#ffffff";
            this._textSprite.bitmap.outlineColor = "rgba(0,0,0,0.8)";
            this._textSprite.bitmap.outlineWidth = 4;
            // Use full width/height, offset the origin
            this._textSprite.bitmap.drawText(
                this._text,
                this._textOffsetX,
                this._textOffsetY,
                this._width,
                this._height,
                "center"
            );
            this.addChild(this._textSprite);
        }
    }

    setHovered(hovered) {
        if (this._isHovered === hovered) return;
        this._isHovered = hovered;
        if (this._idleSprite) this._idleSprite.visible = !hovered;
        if (this._hoverSprite) this._hoverSprite.visible = hovered;
    }

    containsPoint(x, y) {
        var wx = this.x;
        var wy = this.y;
        var parent = this.parent;
        while (parent && parent !== SceneManager._scene) {
            wx += parent.x || 0;
            wy += parent.y || 0;
            parent = parent.parent;
        }
        return x >= wx && x <= wx + this._width &&
            y >= wy && y <= wy + this._height;
    }

    onClick() {
        if (this._onClick) this._onClick();
    }

    destroy(options) {
        if (this._idleSprite) { this._idleSprite.destroy(); this._idleSprite = null; }
        if (this._hoverSprite) { this._hoverSprite.destroy(); this._hoverSprite = null; }
        if (this._textSprite) { this._textSprite.destroy(); this._textSprite = null; }
        super.destroy(options);
    }
};


//=============================================================================
// LPHUDStatus.js
//=============================================================================

LOGICPULSE.UI = LOGICPULSE.UI || {};

LOGICPULSE.UI.StatusDisplay = class extends PIXI.Container {
    constructor(options) {
        super();
        options = options || {};
        this._provider = options.provider || LOGICPULSE.HUDProvider;
        this._layout = options.layout || LOGICPULSE.HUDLayout.CharacterStatusBox;

        // Position the container at the CharacterStatusBox location
        var boxPos = this._getBoxPosition("CharacterStatusBox");
        this.x = boxPos.x;
        this.y = boxPos.y;

        this._createGauges();
        this._createStatsTexts();
        this.updateAll();
    }

    _getBoxPosition(key) {
        var layoutImages = LOGICPULSE.HUDLayout.Images;
        for (var i = 0; i < layoutImages.length; i++) {
            if (layoutImages[i].key === key) {
                return { x: layoutImages[i].x, y: layoutImages[i].y };
            }
        }
        return { x: 0, y: 0 };
    }

    _createGauges() {
        this._gauges = {};
        var gaugeLayout = this._layout.Gauges;
        for (var key in gaugeLayout) {
            var cfg = gaugeLayout[key];
            var container = new PIXI.Container();
            container.x = cfg.x;
            container.y = cfg.y;

            // Prefix label (e.g., "HP")
            var labelWidth = 30;
            var labelText = new LOGICPULSE.UI.Text({
                x: -labelWidth - 4,
                y: 0,
                width: labelWidth,
                height: cfg.H,
                fontSize: cfg.fontSize || 16,
                textColor: cfg.color || "#ffffff",
                align: "right",
                fontFace: $gameSystem.mainFontFace()
            });
            labelText.setText(key);
            container.addChild(labelText);

            // Bar background
            var bg = new PIXI.Graphics();
            bg.beginFill(0x333333);
            bg.drawRect(0, 0, cfg.W, cfg.H);
            bg.endFill();
            container.addChild(bg);

            // Bar fill
            var fillColor = parseInt(cfg.color.replace('#', ''), 16) || 0xffffff;
            var fill = new PIXI.Graphics();
            fill.beginFill(fillColor);
            fill.drawRect(0, 0, cfg.W, cfg.H);
            fill.endFill();
            container.addChild(fill);

            this._gauges[key] = {
                container: container,
                fill: fill,
                maxWidth: cfg.W,
                height: cfg.H,
                color: fillColor
            };
            this.addChild(container);
        }
    }

    _createStatsTexts() {
        this._statsTexts = {};
        var layout = this._layout;
        var keys = ["Attack", "Defence", "agility", "MagicAttack", "MagicDefence", "Weapon", "Shield", "Head", "Body", "Accessory"];
        for (var i = 0; i < keys.length; i++) {
            var key = keys[i];
            var cfg = layout[key];
            if (!cfg) continue;
            var text = new LOGICPULSE.UI.Text({
                x: cfg.x,
                y: cfg.y,
                width: cfg.w,
                height: cfg.h,
                fontSize: cfg.fontSize,
                textColor: cfg.color,
                align: cfg.align || "left",
                fontFace: cfg.font || $gameSystem.mainFontFace()
            });
            this.addChild(text);
            this._statsTexts[key] = text;
        }
    }

    updateAll() {
        this.updateGauges();
        this.updateStatsTexts();
    }

    updateGauges() {
        var provider = this._provider;
        var gauges = {
            HP: { value: provider.getHp(), max: provider.getMaxHp() },
            MP: { value: provider.getMp(), max: provider.getMaxMp() },
            TP: { value: provider.getTp(), max: provider.getMaxTp() }
        };
        for (var key in gauges) {
            var g = this._gauges[key];
            if (!g) continue;
            var val = gauges[key].value;
            var max = gauges[key].max || 1;
            var ratio = Math.min(1, Math.max(0, val / max));
            var newWidth = Math.floor(ratio * g.maxWidth);
            g.fill.clear();
            g.fill.beginFill(g.color);
            g.fill.drawRect(0, 0, newWidth, g.height);
            g.fill.endFill();
        }
    }

    updateStatsTexts() {
        var provider = this._provider;
        this._statsTexts.Attack.setText("ATK: " + provider.getAttack());
        this._statsTexts.Defence.setText("DEF: " + provider.getDefence());
        this._statsTexts.agility.setText("AGI: " + provider.getAgility());
        this._statsTexts.MagicAttack.setText("MAT: " + provider.getMagicAttack());
        this._statsTexts.MagicDefence.setText("MDF: " + provider.getMagicDefence());
        this._statsTexts.Weapon.setText("WPN: " + provider.getWeapon());
        this._statsTexts.Shield.setText("SH: " + provider.getShield());
        this._statsTexts.Head.setText("HD: " + provider.getHead());
        this._statsTexts.Body.setText("BD: " + provider.getBody());
        this._statsTexts.Accessory.setText("ACC: " + provider.getAccessory());
    }
};


